export const simulationGuides=[
extra('worldsimready','WorldSimReady-Home：家居仿真数据集','Yootta 发布的家居仿真场景与机器人任务数据集，在 ModelScope/Hugging Face 提供入口；它是环境与数据资源，不是一个可直接调用生成内容的模型权重。','embodied',10,'https://github.com/YoottaAI/World-SimReady-Home',[
 '团队需要多种户型、家具布局和可重复交互数据，仅靠自己从零造房屋耗时。WorldSimReady-Home 这类资源为场景和任务数据提供起点，再由具体算法与训练器消费。',
 ['像一批已经搭好的训练房屋和练习录像：房屋提供场地，录像提供示范，学习方法还要另外安排。','数据集不是会行动的大脑；场景可导入、轨迹可读取，也不等于已经训练好机器人。'],
 ['先在公开数据集卡区分 scene 与 task 两类产物：前者描述环境，后者记录交互。','教学使用设想：从一个有效场景运行不同起点/目标，检查可达性，再生成自己的回合。','若使用已有轨迹训练，先检查观测、动作、时间与机器人接口，再决定做行为克隆或状态转移预测；不能直接把任何录像当作可用标签。'],
 ['从官方仓库与数据集卡核对发布者、版本、文件结构和使用许可。','先审一个场景和一条回合，验证坐标、动作表示、时间对齐与终止语义。','按独立房屋划分数据，再接仿真器、任务与训练器；记录本次实际验收范围。'],
 '减少从零准备家居场景与任务数据的重复工作，便于构建可复查的训练环境。','公开数据存在不等于当前机器人接口兼容或真实部署有效；同事使用的具体版本和流程仍需核对。本平台未下载大规模资产或运行该数据集的完整仿真。',
 ['ModelScope 页面里找到 WorldSimReady-Home，就意味着可以像语言模型一样输入提示词生成房子吗？','不能这样推断。先看页面类型和产物：已核对的项目是数据集，生成工具、仿真执行和模型训练是另外的步骤。']]),
extra('simready','SimReady / 仿真就绪资产','资产除外观外，还要满足目标仿真用途需要的几何、物理、语义和行为等要求；NVIDIA SimReady 提供相关 OpenUSD 规范与验证体系。','embodied',10,sim,[
 '机器人不仅看椅子，还可能撞到它、推它、辨认它。只有漂亮网格而没有正确尺度或碰撞，训练出来的行为可能利用虚假环境漏洞。',
 ['舞台上的门板看起来是门，真正的门还需门轴、可开启范围和不会穿透的边界。','不同用途需要不同属性：只做静态视觉识别与练开门动作的要求并不完全相同。'],
 ['教学资产 chair_01 的视觉网格负责成像，碰撞形状负责接触计算。','米/厘米弄错 100 倍，外观在缩放镜头中仍可像椅子，机器人通行与抓取却会失效。','只有任务需要推动或关节交互时，才进一步验证质量、摩擦、关节限制等对应条件。'],
 ['先写资产将用于视觉、导航还是操纵。','依据目标运行时与规范验证单位、轴、碰撞、语义及所需物理属性。','在实际仿真器执行放置、接触或关节测试，并保存版本与来源。'],
 '可复用且经过检查的资产减少每次搭环境的重复工作。','资产符合某个规范不等于真实物理已标定，也不保证跨所有运行时一致；视觉逼真不能代替任务有效性。',
 ['静态椅子能显示，是否证明它可被可靠推动？','不能，还需动态物理、接触、尺度等检查，且按目标任务验证。']]),
extra('scene-layout','户型、场景图与 OpenUSD','户型描述空间布局，场景图组织物体与变换；OpenUSD 可组合与交换场景描述，但场景描述本身不执行机器人任务。','embodied',10,'https://openusd.org/release/intro.html',[
 '孤立的桌子、门和机器人不能组成有效任务。需要约定它们在哪里、属于哪个房间、尺寸多少、如何连接和引用。',
 ['装修图标出房间、门和家具；施工还要把图中的位置与真实尺寸对应起来。','房间邻接图不是所有细节的替代，门是否锁住、通道宽度等仍需其他数据。'],
 ['设客厅与厨房通过宽 0.8 米的门相连，机器人宽 0.6 米。','把沙发移动到门边后，房间名没变，但通行条件可能改变。','用 assets/ 保存可复用物体，scenes/ 引用资产并指定位置；变更布局要版本化。'],
 ['明确坐标轴、单位、父子变换与资产路径。','检查墙体闭合、门连通、物体重叠和起点目标有效性。','程序化生成更多户型后做同样校验，不把生成数量直接当数据质量。'],
 '把资产与布局分开，便于复用、变体生成和定位错误。','语义合理的房间也可能在几何或物理上不可用；OpenUSD 文件不是自动可执行的导航策略。',
 ['给同一户型换十种墙纸，等于十种独立空间布局吗？','不等于；外观变化与结构变化应分别统计和划分。']]),
extra('scene-physics','视觉几何、碰撞体与关节','视觉几何决定看起来怎样，碰撞体决定何处发生接触，关节限制物体部件之间的运动。','embodied',10,'https://github.com/NVIDIA/simready-foundation',[
 '渲染和物理往往使用不同表示以控制成本。如果碰撞体错误，机器人可能穿桌、卡门，或把不能开的柜门当作可操作。',
 ['一张桌子照片没有可供手碰到的桌面；可交互模型还需要关于接触和运动的约定。','碰撞体通常是近似，不要求把每个细小纹理都做成物理几何。'],
 ['桌面视觉网格很薄，但碰撞箱可能太厚，堵住本来能通过的空间。','柜门绕铰链轴旋转，需要正确的关节轴、范围与初态。','“夹爪接触物体”和“物体随夹爪移动”之间，还取决于摩擦、动力学和控制。'],
 ['分别显示视觉与碰撞几何检查错位。','用已知简单动作测试接触、重力与关节运动。','调整近似复杂度后同时量质量与仿真速度。'],
 '能把静态外观扩展成可交互环境，并控制接触计算成本。','不合理的近似和未标定参数会制造仿真捷径；更复杂几何也可能更慢或更不稳定。',
 ['导航地图没障碍，机器人仍卡住，除了策略还能查什么？','碰撞形状、尺度、机器人尺寸、地图构建与动态障碍是否一致。']]),
extra('navmesh','可通行区域、占据栅格与 NavMesh','占据栅格按格子描述障碍，NavMesh 用多边形表示可导航表面；可通行性与机器人尺寸及运动约束有关。','embodied',10,'https://aihabitat.org/docs/habitat-sim/habitat_sim.nav.PathFinder.html',[
 '图像中的空白不等于机器人可以走。规划需要可计算的空间表示，还要给机器人身体留出余量。',
 ['人能侧身经过的缝，不一定够搬一张桌子通过；路径要按经过者尺寸判断。','平面路径通常忽略部分动力学或三维姿态，不能自动保证真实执行。'],
 ['门宽 0.8 米，圆形机器人半径 0.3 米，每侧留 0.05 米，总需求 0.7 米。','若半径增至 0.4 米，同样余量要求 0.9 米，这扇门应判为不可通过。','在栅格中可先把障碍按机器人半径膨胀，再为机器人中心找路径；这只是离散近似。'],
 ['指定机器人尺寸、坡度/台阶能力与地图分辨率。','检查起点和目标是否处于同一可通行连通区域。','家具移动或门状态变化后更新相应表示，执行时继续检查碰撞。'],
 '把复杂空间转成可搜索的连通关系，能建立清楚的规划基线。','粗栅格会丢窄通道；静态 NavMesh 不能独自应对所有动态物体、感知误差和运动约束。',
 ['点机器人规划能过门，真实底盘一定能过吗？','不能，需考虑尺寸、安全余量和执行约束。']]),
extra('navigation','机器人导航、PointNav、ObjectNav 与 VLN','导航要求从观测与目标决定移动，并按任务协议到达目标；目标可为坐标、物体类别或语言指令。','embodied',10,habitat,[
 '会预测下一帧或识别沙发，不等于会从厨房走到沙发旁。导航还需要定位、探索或地图、行动选择、终止和验收。',
 ['在陌生商场找洗手间，要观察标识、选择路线并确认到达；不是只说出“洗手间”的名字。','导航任务提供的信息差异很大，给全图坐标与只给相机图像不是相同难度。'],
 ['PointNav：给目标位置，明确坐标参考系与允许的传感器。','ObjectNav：找某类物体，可能不知道其位置；VLN 还要依语言描述完成路径或目标要求。','一回合最短有效路径为 4 米，实际成功走 6 米，则本回合 SPL=4/6；失败记 0。'],
 ['定义 reset 的起点、目标、观测、动作、碰撞与停止条件。','先做已知地图的搜索基线，再逐步去掉全图等特权信息。','按独立房屋评估成功率、路径效率与碰撞；协议不同不能直接比分数。'],
 '提供连接感知、记忆、规划与控制的完整任务。','最短路径只适用于特定地图和运动定义；高仿真成功率不自动证明真实部署能力。',
 ['BFS 在已知栅格找到路，是否完成视觉导航训练？','没有，它是规划基线；视觉观测、定位、探索和学习策略还未实现。']]),
extra('simulator','仿真器、环境与学习型世界模型','仿真器按场景和规则推进状态并生成观测；环境再定义任务与奖励。学习型世界模型从数据拟合状态或观测变化。','embodied',10,habitat,[
 '“world”可以指场景，也可指预测模型。区分环境真值如何产生与模型如何近似它，才能设计有效训练和测试。',
 ['飞行模拟器提供练习环境，学员对下一秒发生什么的预测是另一个东西。','复杂系统可混合物理与学习模块，不能仅按名字判断内部机制。'],
 ['环境 reset 载入房屋、机器人初态和目标。','step(action) 由仿真推进，返回观测、奖励、结束信息。','记录 (obs,action,next_obs) 可监督世界模型；用奖励可训练策略；保存教师动作可做行为克隆。'],
 ['分别写场景文件、动力学、传感器、任务与模型接口。','先检查时间步、动作单位、相机时间戳和终止语义。','若使用学习模型替代部分环境，单独记录预测误差与误差累积。'],
 '可重复、可控制地采样任务与故障，为训练提供数据和反馈。','仿真精度与速度有取舍，模型可能利用仿真缺陷；学习型世界模型也会偏离真实后果。',
 ['导入一个房屋 USD 后就训练了世界模型吗？','没有，那是准备环境；还需数据、学习目标、参数更新与评测。']]),
extra('domain-randomization','域随机化与合成数据','在有记录的分布内改变外观、布局、物理或传感器条件，生成多样环境与数据，帮助检验和学习鲁棒性。','embodied',10,'https://arxiv.org/abs/1703.06907',[
 '训练只见一个固定房间，模型可能记住墙纸或固定目标位置。受控变化让你观察它依赖什么，也可扩展训练条件。',
 ['练习开车时遇到不同光照、路面和路况，而不是只反复同一晴天直路。','不是越离谱越好；随机化范围应与真实用途和物理可行性相关。'],
 ['先固定房型，只换光照，测试外观鲁棒性。','再改家具位置并重新校验通行，测试结构泛化。','若改摩擦或噪声，记录参数及随机种子，使失败回合可复现。'],
 ['一次先变化一个维度建立诊断，再组合有依据的变化。','拒绝物体穿插、目标不可达等不符合任务的样本。','按房屋/布局源划分训练测试，再随机化；合成标签也需时间和坐标对齐。'],
 '可扩大场景覆盖，获得自动标签并发现脆弱条件。','无效随机化浪费计算，过宽分布可能增加学习难度；更多合成样本不保证更好真实效果。',
 ['同一房屋换纹理后放测试集，就能证明新户型泛化吗？','不能，只能支持相应外观变化下的结论，还需独立布局测试。']]),
extra('sim2real','Sim-to-Real 与仿真差距','把仿真中得到的能力迁移到真实环境，需要处理几何、外观、动力学、传感器与控制等差异，并用真实证据验证。','embodied',10,'https://arxiv.org/abs/1703.06907',[
 '真实地面摩擦、相机延迟、标定误差不一定与仿真一致。仿真成绩只是某组假设下的结果，需要检查这些假设是否成立。',
 ['在模拟考里答得很好，仍要面对实际考场的新条件；需要明确哪些变化可能影响表现。','这里只类比迁移差异，不意味着机器人可以像人一样凭经验自动适应。'],
 ['仿真动作持续 0.1 秒，真实控制链存在延迟，机器人实际停止更晚。','感知模型在干净深度图中有效，遇到真实缺失深度可能失效。','先在受控真实场景测误差，再决定校准、补真实数据或重新训练。'],
 ['列出最可能的差距及可测量量。','将标定/随机化/真实微调与各自消融对应。','由有权限的团队按实际机器人测试流程递进验证，报告未验证范围。'],
 '能系统定位仿真到实际表现下降的原因。','真实采集与验证有成本；域随机化或更逼真渲染不是通用迁移保证。',
 ['仿真成功率 100%，能直接写真实成功率 100% 吗？','不能，必须独立测量真实任务并说明条件。']])
];
